// Version: 1.0.0
// mvu_zod reusable schema bridge
// Source: https://github.com/StageDog/tavern_resource
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

const api = Object.freeze({ registerMvuSchema });
Object.defineProperty(window.parent, 'MvuZod', {
  configurable: true,
  value: api,
});

window.addEventListener('pagehide', () => {
  if (window.parent.MvuZod === api) {
    delete window.parent.MvuZod;
  }
}, { once: true });
